after_block:
# A map alias to a missing hash slot would autovivify that slot in
# the original context. Absence is intentional for this control.
$value->{archive} = exists($context->{archives}{$name})
    ? clone($context->{archives}{$name}) : undef;
@$value{qw(selection settlement)} = map { clone($_) }
    ($context->{selections}{$name}, $context->{settlements}{$name});
